Extensions.ExtractScript:
param(
    [xml] $Document
);

foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
$excludes = Get-ChildItem -LiteralPath 'Registry::HKU\DefaultUser\AppEvents\EventLabels' |
    Where-Object -FilterScript { ($_ | Get-ItemProperty).ExcludeFromCPL -eq 1; } |
    Select-Object -ExpandProperty 'PSChildName';
Get-ChildItem -Path 'Registry::HKU\DefaultUser\AppEvents\Schemes\Apps\*\*' |
    Where-Object -Property 'PSChildName' -NotIn $excludes |
    Get-ChildItem -Include '.Current' | Set-ItemProperty -Name '(Default)' -Value '';

$lightThemeSystem = 1;
$lightThemeApps = 1;
$accentColorOnStart = 0;
$enableTransparency = 1;
$htmlAccentColor = '#0078D4';
& {
	$params = @{
		LiteralPath = 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize';
		Force = $true;
		Type = 'DWord';
	};
	Set-ItemProperty @params -Name 'SystemUsesLightTheme' -Value $lightThemeSystem;
	Set-ItemProperty @params -Name 'AppsUseLightTheme' -Value $lightThemeApps;
	Set-ItemProperty @params -Name 'ColorPrevalence' -Value $accentColorOnStart;
	Set-ItemProperty @params -Name 'EnableTransparency' -Value $enableTransparency;
};
& {
	Add-Type -AssemblyName 'System.Drawing';
	$accentColor = [System.Drawing.ColorTranslator]::FromHtml( $htmlAccentColor );

	function ConvertTo-DWord {
		param(
			[System.Drawing.Color]
			$Color
		);

		[byte[]] $bytes = @(
			$Color.R;
			$Color.G;
			$Color.B;
			$Color.A;
		);
		return [System.BitConverter]::ToUInt32( $bytes, 0); 
	}

	$startColor = [System.Drawing.Color]::FromArgb( 0xD2, $accentColor );
	Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent' -Name 'StartColorMenu' -Value( ConvertTo-DWord -Color $accentColor ) -Type 'DWord' -Force;
	Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent' -Name 'AccentColorMenu' -Value( ConvertTo-DWord -Color $accentColor ) -Type 'DWord' -Force;
	Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\DWM' -Name 'AccentColor' -Value( ConvertTo-DWord -Color $accentColor ) -Type 'DWord' -Force;
	$params = @{
		LiteralPath = 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Accent';
		Name = 'AccentPalette';
	};
	$palette = Get-ItemPropertyValue @params;
	$index = 20;
	$palette[ $index++ ] = $accentColor.R;
	$palette[ $index++ ] = $accentColor.G;
	$palette[ $index++ ] = $accentColor.B;
	$palette[ $index++ ] = $accentColor.A;
	Set-ItemProperty @params -Value $palette -Type 'Binary' -Force;
};

Add-Type -TypeDefinition '
	using System.Drawing;
	using System.Runtime.InteropServices;

	public static class WallpaperSetter {
		[DllImport("user32.dll")]
		private static extern bool SetSysColors(
			int cElements, 
			int[] lpaElements,
			int[] lpaRgbValues
		);

		[DllImport("user32.dll")]
		private static extern bool SystemParametersInfo(
			uint uiAction,
			uint uiParam,
			string pvParam,
			uint fWinIni
		);

		public static void SetDesktopBackground(Color color) {
			SystemParametersInfo(20, 0, "", 0);
			SetSysColors(1, new int[] { 1 }, new int[] { ColorTranslator.ToWin32(color) });
		}

		public static void SetDesktopImage(string file) {
			SystemParametersInfo(20, 0, file, 0);
		}
	}
' -ReferencedAssemblies 'System.Drawing';

function Set-WallpaperColor {
	param(
		[string]
		$HtmlColor
	);

	$color = [System.Drawing.ColorTranslator]::FromHtml( $HtmlColor );
	[WallpaperSetter]::SetDesktopBackground( $color );
	Set-ItemProperty -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers' -Name 'BackgroundType' -Type 'DWord' -Value 1 -Force;
	Set-ItemProperty -Path 'Registry::HKCU\Control Panel\Desktop' -Name 'WallPaper' -Type 'String' -Value '' -Force;
	Set-ItemProperty -Path 'Registry::HKCU\Control Panel\Colors' -Name 'Background' -Type 'String' -Value "$($color.R) $($color.G) $($color.B)" -Force;
}

function Set-WallpaperImage {
	param(
		[string]
		$LiteralPath
	);

	if( $LiteralPath | Test-Path ) {
		[WallpaperSetter]::SetDesktopImage( $LiteralPath );
		Set-ItemProperty -Path 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers' -Name 'BackgroundType' -Type 'DWord' -Value 0 -Force;
		Set-ItemProperty -Path 'Registry::HKCU\Control Panel\Desktop' -Name 'WallPaper' -Type 'String' -Value $LiteralPath -Force;
	} else {
		"Cannot use '$LiteralPath' as a desktop wallpaper because that file does not exist.";
	}
}
Set-WallpaperColor -HtmlColor '#000000';

# Autotuning Internet Speed and making it persistent Set-NetTCPSetting -SettingName * -ScalingHeuristics Disabled Set-NetTCPSetting -SettingName * -InitialRto 3000 -Timestamps Disabled -MemoryPressureProtection Disabled -NonSackRttResiliency Disabled -MaxSynRetransmissions 2 Set-NetIPv4Protocol -IcmpRedirects Disabled -DefaultHopLimit 64 -MultipleArpAnnouncements Disabled
netsh.exe interface tcp set supplemental Internet congestionprovider=ctcp netsh.exe interface tcp set supplemental InternetCustom congestionprovider=ctcp netsh.exe interface tcp set supplemental Datacenter congestionprovider=ctcp netsh.exe interface tcp set supplemental Compat congestionprovider=ctcp netsh.exe interface tcp set supplemental DatacenterCustom congestionprovider=ctcp
# OffloadGlobal Settings Set-NetOffloadGlobalSetting -PacketCoalescingFilter disabled -Chimney Disabled -Taskoffload Enabled -ReceiveSideScaling Enabled -ReceiveSegmentCoalescing Disabled
# tweaking features from network adapters Disable-NetAdapterLso -Name * Disable-NetAdapterBinding -Name * -ComponentID ms_pacer Set-NetIPInterface -WeakHostSend Enabled -WeakHostReceive Enabled -ErrorAction SilentlyContinue
# TCP/IP Protocole Tweaks netsh.exe int isatap set state disable | Out-Null netsh.exe int tcp set global ecncapability=enabled | Out-Null netsh.exe int tcp set global ecn=enabled | Out-Null netsh.exe interface tcp set global fastopen=enabled | Out-Null netsh.exe interface tcp set global fastopenfallback=enabled | Out-Null netsh.exe interface ip set global neighborcachelimit=4096 taskoffload=enabled | Out-Null netsh.exe interface tcp set global hystart=disabled | Out-Null
# Function to add or update registry keys function Set-RegKey { param ( [string]$path, [string]$name, [string]$value, [string]$type = "DWord" )
if ($type -eq "DWord") { Set-ItemProperty -Path $path -Name $name -Value $value -Type DWord -Force } else { Set-ItemProperty -Path $path -Name $name -Value $value -Type String -Force } }
# Adding NetBIOS Options $netbtPath = "HKLM:\SYSTEM\CurrentControlSet\services\NetBT\Parameters\Interfaces" $interfaces = Get-ChildItem -Path $netbtPath
foreach ($interface in $interfaces) { Set-RegKey -path $interface.PSPath -name "NetbiosOptions" -value 1 -type "DWord" }
# Updating registry keys for network interfaces $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces" $networkInterfaces = Get-ChildItem -Path $regPath | Where-Object { $_.Name -match "000" }
foreach ($interface in $networkInterfaces) { # Disable Flow Control Set-RegKey -path $interface.PSPath -name "*FlowControl" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "FlowControlCap" -value "0" -type "String"
# Remove Interrupt Delays Set-RegKey -path $interface.PSPath -name "TxIntDelay" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "TxAbsIntDelay" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "RxIntDelay" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "RxAbsIntDelay" -value "0" -type "String"
# Remove Adapter Notification Set-RegKey -path $interface.PSPath -name "FatChannelIntolerant" -value "0" -type "String"
# Disable Interrupt Moderation Set-RegKey -path $interface.PSPath -name "*InterruptModeration" -value "0" -type "String"
# Disable - Allow the computer to turn off this device to save power Set-RegKey -path $interface.PSPath -name "LogDisconnectEvent" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "LogLinkStateEvent" -value 16 -type "String"
# Disable - Reduce network speed to 10/100 Set-RegKey -path $interface.PSPath -name "GigaLite" -value "0" -type "String"
# Disabling Green Ethernet Set-RegKey -path $interface.PSPath -name "*EEE" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "AdvancedEEE" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "AutoPowerSaveModeEnabled" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "EnableEDT" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "EnableGreenEthernet" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "EEELinkAdvertisement" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "ENPWMode" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "GPPSW" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "PowerSavingMode" -value "0" -type "String" Set-RegKey -path $interface.PSPath -name "ULPMode" -value "0" -type "String" }
# Disabling Nagle's Algorithm for better Gaming Latency $tcpipPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces" $tcpInterfaces = Get-ChildItem -Path $tcpipPath | Where-Object { $_.Name -match "1" }
foreach ($tcpInterface in $tcpInterfaces) { Set-RegKey -path $tcpInterface.PSPath -name "TCPNoDelay" -value 1 -type "DWord" Set-RegKey -path $tcpInterface.PSPath -name "TcpAckFrequency" -value 1 -type "DWord" Set-RegKey -path $tcpInterface.PSPath -name "TcpDelAckTicks" -value 0 -type "DWord" }
# A string list which has listed capabilities or FoD to be disabled and removed. $flist = @("*Realtek*", "*Intel*", "*Broadcom*", "*Qualcomm*", "*Marvel*", "*Vmware*", "*Ethernet*", "*InternetExplorer*", "*StepsRecorder*", "*WindowsMediaPlayer*", "*Wallpapers*", "*Print*", "*MathRecognizer*", "*PowerShell*", "*QuickAssist*", "*OneSync*", "*LA57*", "*Ralink*", "*Virtual*", "*TCP*", "*Hello*","*Theme*","*Edge*")
foreach ($item in $flist) { # Get the list of capabilities that match the current item $checkCapabilities = Get-WindowsCapability -Online | Where-Object { $_.Name -like $item }
foreach ($checkCapability in $checkCapabilities) { if ($checkCapability.State -eq 'Installed') { try { # Remove each capability found Remove-WindowsCapability -Online -Name $checkCapability.Name -ErrorAction Stop } catch { Write-Host "Error at $($checkCapability.Name): $($_.Exception.Message)" } } } }
$Host.UI.RawUI.WindowTitle = "Unsplitter" Set-Location -Path $PSScriptRoot $os = Get-WmiObject -Class Win32_OperatingSystem $mem = $os.TotalVisibleMemorySize $ram = $mem + 1024000 Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control" -Name "SvcHostSplitThresholdInKB" -Value $ram -Type DWord

